static const UINT8 *FontCjk16Lookup(UINT32 Cp) {
    UINT32 Lo = 0;
    UINT32 Hi = FONT_CJK16_COUNT;
    while (Lo < Hi) {
        UINT32 Mid = Lo + (Hi - Lo) / 2u;
        UINT32 V = gFontCjk16[Mid].Cp;
        if (V == Cp) { return gFontCjk16[Mid].Bits; }
        if (V < Cp) { Lo = Mid + 1u; } else { Hi = Mid; }
    }
    return 0;
}

